<?php
declare(strict_types=1);
/** Explicit paired-device task sync; transport holds only authenticated ciphertext. */
final class DeviceSyncService {
    public static function identity():array{
        if(!extension_loaded('sodium'))throw new InvalidArgumentException(t('Device sync requires the Sodium extension.'));
        $path=DATA.'/.platform-device-key';if(!is_file($path)){$pair=sodium_crypto_box_keypair();$f=@fopen($path,'xb');if($f){chmod($path,0600);fwrite($f,$pair);fclose($f);}}
        $key=file_get_contents($path);if(strlen($key)!==SODIUM_CRYPTO_BOX_KEYPAIRBYTES)throw new RuntimeException(t('Device key is invalid.'));$public=sodium_crypto_box_publickey($key);return ['key'=>$key,'public'=>base64_encode($public),'id'=>hash('sha256',$public)];
    }
    public static function pair(string $name,string $public):void{$key=base64_decode($public,true);if(!$key||strlen($key)!==32||strlen($name)>100||trim($name)==='')throw new InvalidArgumentException(t('Enter a device name and its public key.'));$me=self::identity();$id=hash('sha256',$key);if($id===$me['id'])throw new InvalidArgumentException(t('Pair a different device.'));Db::run('INSERT INTO platform_peers(id,name,public_key) VALUES(?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,revoked=0',[$id,trim($name),base64_encode($key)]);PlatformService::audit('device-paired',$id);}
    private static function peer(string $id):array{$peer=Db::one('SELECT * FROM platform_peers WHERE id=? AND revoked=0',[$id]);if(!$peer)throw new InvalidArgumentException(t('Device is not paired or was revoked.'));return $peer;}
    public static function packet(string $peerId):string{
        $me=self::identity();$peer=self::peer($peerId);$items=[];
        foreach(Db::all("SELECT id,title,due,status FROM tasks WHERE source IN ('planner','platform-import','device-sync') ORDER BY id LIMIT 1001")as $task){if(count($items)>=1000)throw new InvalidArgumentException(t('Sync currently supports at most 1000 tasks.'));$uuid=SyncIdentity::forRow('tasks',(int)$task['id']);unset($task['id']);$items[]=['id'=>$uuid,'task'=>$task];}
        $plain=json_encode(['version'=>1,'tasks'=>$items],JSON_THROW_ON_ERROR);$nonce=random_bytes(SODIUM_CRYPTO_BOX_NONCEBYTES);$key=sodium_crypto_box_keypair_from_secretkey_and_publickey(sodium_crypto_box_secretkey($me['key']),base64_decode($peer['public_key']));$cipher=sodium_crypto_box($plain,$nonce,$key);return json_encode(['v'=>1,'from'=>$me['id'],'to'=>$peerId,'nonce'=>base64_encode($nonce),'data'=>base64_encode($cipher)],JSON_THROW_ON_ERROR);
    }
    public static function preview(string $packet):array{
        if(strlen($packet)>2097152)throw new InvalidArgumentException(t('Sync packet too large.'));$p=json_decode($packet,true,16,JSON_THROW_ON_ERROR);$me=self::identity();if(!is_array($p)||($p['v']??null)!==1||($p['to']??'')!==$me['id'])throw new InvalidArgumentException(t('Packet is not for this device.'));$peer=self::peer((string)($p['from']??''));$nonce=base64_decode($p['nonce']??'',true);$cipher=base64_decode($p['data']??'',true);if(!$nonce||strlen($nonce)!==24||!$cipher)throw new InvalidArgumentException(t('Invalid encrypted packet.'));$key=sodium_crypto_box_keypair_from_secretkey_and_publickey(sodium_crypto_box_secretkey($me['key']),base64_decode($peer['public_key']));$plain=sodium_crypto_box_open($cipher,$nonce,$key);if($plain===false)throw new InvalidArgumentException(t('Packet authentication failed.'));$payload=json_decode($plain,true,32,JSON_THROW_ON_ERROR);if(($payload['version']??null)!==1||!is_array($payload['tasks']??null)||count($payload['tasks'])>1000)throw new InvalidArgumentException(t('Invalid sync task list.'));$rows=[];$seen=[];
        foreach($payload['tasks']as $item){$uuid=$item['id']??'';$task=$item['task']??null;if(!is_string($uuid)||!preg_match('/^[a-f0-9]{64}:[1-9][0-9]*$/D',$uuid)||isset($seen[$uuid])||!is_array($task))throw new InvalidArgumentException(t('Invalid or repeated sync record.'));$seen[$uuid]=true;PlatformService::preview(json_encode([$task]),'json');if(!in_array($task['status']??'', ['open','done'],true))throw new InvalidArgumentException(t('Invalid task state.'));$task=['title'=>$task['title'],'due'=>$task['due']??null,'status'=>$task['status']];$map=Db::one('SELECT * FROM platform_sync_map WHERE peer=? AND remote_id=?',[$peer['id'],$uuid]);$local=$map?Db::one('SELECT title,due,status FROM tasks WHERE id=?',[$map['local_id']]):null;$localId=$map['local_id']??null;
            if(!$map){$native=Db::one('SELECT row_id FROM platform_local_ids WHERE kind=? AND uuid=?',['tasks',$uuid]);if($native){$localId=$native['row_id'];$local=Db::one('SELECT title,due,status FROM tasks WHERE id=?',[$localId]);}}
            if($local!==null){$source=Db::one('SELECT source FROM tasks WHERE id=?',[$localId])['source'];if(!in_array($source,['planner','platform-import','device-sync'],true))throw new InvalidArgumentException(t('Linked module tasks use their own domain workflows and cannot be overwritten by sync.'));}
            $base=$map&&$map['base_json']!==null?json_decode($map['base_json'],true):null;$conflict=($local!==null&&$local!==$task&&$local!==$base)||($map&&$local===null);$rows[]=['id'=>$uuid,'task'=>$task,'local'=>$local,'local_id'=>$localId,'conflict'=>$conflict];
        }return ['peer'=>$peer['id'],'hash'=>hash('sha256',$packet),'rows'=>$rows];
    }
    public static function apply(string $packet,array $choices):void{$preview=self::preview($packet);Db::tx(function()use($preview,$choices){if(Db::one('SELECT hash FROM platform_sync_packets WHERE hash=?',[$preview['hash']]))throw new InvalidArgumentException(t('This packet was already processed.'));foreach($preview['rows']as $row){$choice=$choices[$row['id']]??'';if($row['conflict']&&!in_array($choice,['local','remote'],true))throw new InvalidArgumentException(t('Resolve every conflict.'));if($row['conflict']&&$choice==='local')continue;$t=$row['task'];if($row['local']===null){$id=Db::run("INSERT INTO tasks(title,due,status,source,completed_at) VALUES(?,?,?,'device-sync',?)",[$t['title'],$t['due'],$t['status'],null]);}else{$id=$row['local_id'];Db::run('UPDATE tasks SET title=?,due=?,status=?,completed_at=CASE WHEN ?=\'done\' THEN completed_at ELSE NULL END WHERE id=?',[$t['title'],$t['due'],$t['status'],$t['status'],$id]);}SyncIdentity::bind('tasks',(int)$id,$row['id']);Db::run('INSERT INTO platform_sync_map(peer,remote_id,local_id,base_json) VALUES(?,?,?,?) ON CONFLICT(peer,remote_id) DO UPDATE SET local_id=excluded.local_id,base_json=excluded.base_json',[$preview['peer'],$row['id'],$id,json_encode($t)]);}Db::run('INSERT INTO platform_sync_packets(hash) VALUES(?)',[$preview['hash']]);PlatformService::audit('device-synced',$preview['peer'].'; '.count($preview['rows']).' tasks reviewed');});}
    public static function recovery(string $passphrase):string{if(strlen($passphrase)<12)throw new InvalidArgumentException(t('Use a recovery passphrase with at least 12 characters.'));$me=self::identity();$salt=random_bytes(SODIUM_CRYPTO_PWHASH_SALTBYTES);$key=sodium_crypto_pwhash(SODIUM_CRYPTO_SECRETBOX_KEYBYTES,$passphrase,$salt,SODIUM_CRYPTO_PWHASH_OPSLIMIT_INTERACTIVE,SODIUM_CRYPTO_PWHASH_MEMLIMIT_INTERACTIVE);$nonce=random_bytes(24);return base64_encode($salt.$nonce.sodium_crypto_secretbox($me['key'],$nonce,$key));}
    public static function restore(string $blob,string $passphrase,string $fingerprint):void{
        $raw=base64_decode(trim($blob),true);if(!$raw||strlen($raw)!==16+24+16+64)throw new InvalidArgumentException(t('Invalid recovery file.'));$key=sodium_crypto_pwhash(32,$passphrase,substr($raw,0,16),SODIUM_CRYPTO_PWHASH_OPSLIMIT_INTERACTIVE,SODIUM_CRYPTO_PWHASH_MEMLIMIT_INTERACTIVE);$pair=sodium_crypto_secretbox_open(substr($raw,40),substr($raw,16,24),$key);if($pair===false||strlen($pair)!==64)throw new InvalidArgumentException(t('Recovery passphrase did not match.'));$id=hash('sha256',sodium_crypto_box_publickey($pair));if(!hash_equals($id,$fingerprint))throw new InvalidArgumentException(t('Device fingerprint does not match recovery key.'));$me=self::identity();if($id!==$me['id']&&(Db::one('SELECT id FROM platform_peers LIMIT 1')||Db::one('SELECT peer FROM platform_sync_map LIMIT 1')))throw new InvalidArgumentException(t('Recover keys into a new workspace before pairing devices.'));$path=DATA.'/.platform-device-key';$temp=$path.'.'.bin2hex(random_bytes(8));file_put_contents($temp,$pair,LOCK_EX);chmod($temp,0600);if(!rename($temp,$path)){unlink($temp);throw new RuntimeException(t('Could not restore key.'));}PlatformService::audit('device-key-recovered',$id);
    }
}
